//! Built-in starter content (T-533): a small, read-only library of our own
//! procedural figures and wireframe 3D objects, shown and playable on a
//! fresh data dir so CRÉATION › Figures and CRÉATION › Objets 3D are never
//! empty. Everything here is generated by code (maths over our own
//! parameters): nothing is copied from another product or a protected
//! library. These are never written to disk nor baked into a project; a
//! user figure or object of the same name shadows the built-in, and the
//! operator can play or duplicate them but not delete or overwrite them.

use crate::figures::{Figure, FigureFrame, LoopMode, RateUnit, Stroke};
use crate::wire::WireObject;
use std::f32::consts::{PI, TAU};

/// Green, our default beam colour.
const GREEN: [u8; 3] = [0, 255, 0];
const CYAN: [u8; 3] = [0, 255, 255];
const MAGENTA: [u8; 3] = [255, 0, 255];
const RED: [u8; 3] = [255, 60, 60];
const YELLOW: [u8; 3] = [255, 220, 0];
const BLUE: [u8; 3] = [60, 120, 255];
const WHITE: [u8; 3] = [255, 255, 255];

// ---------------------------------------------------------------------------
// Figures (2D)
// ---------------------------------------------------------------------------

/// One lit stroke of a figure.
fn stroke(points: Vec<[f32; 2]>, color: [u8; 3]) -> Stroke {
    Stroke { points, color, lit: true, part: 0 }
}

/// A closed outline: the first point repeated at the end (patterns rule).
fn closed(mut points: Vec<[f32; 2]>) -> Vec<[f32; 2]> {
    if let Some(&first) = points.first() {
        if points.last() != Some(&first) {
            points.push(first);
        }
    }
    points
}

/// A single-frame figure made of one closed outline.
fn outline(name: &str, color: [u8; 3], points: Vec<[f32; 2]>) -> Figure {
    one_frame(name, vec![stroke(closed(points), color)])
}

/// A single-frame figure made of the given strokes.
fn one_frame(name: &str, strokes: Vec<Stroke>) -> Figure {
    Figure { name: name.to_string(), frames: vec![FigureFrame { strokes }], ..Figure::default() }
}

/// `n` points of a parametric curve, `t` running 0..1 (end included).
fn curve(n: usize, f: impl Fn(f32) -> [f32; 2]) -> Vec<[f32; 2]> {
    (0..=n).map(|i| f(i as f32 / n as f32)).collect()
}

/// A regular polygon of `sides` vertices, radius `r`, first vertex up.
fn polygon(sides: usize, r: f32) -> Vec<[f32; 2]> {
    (0..sides).map(|i| {
        let a = PI / 2.0 + i as f32 / sides as f32 * TAU;
        [r * a.cos(), r * a.sin()]
    }).collect()
}

/// `n + 1` points of a circular arc of centre `c`, radius `r`, from
/// `from_deg` to `to_deg` (degrees), both ends included.
fn arc(c: [f32; 2], r: f32, from_deg: f32, to_deg: f32, n: usize) -> Vec<[f32; 2]> {
    (0..=n)
        .map(|i| {
            let a = (from_deg + (to_deg - from_deg) * i as f32 / n as f32).to_radians();
            [c[0] + r * a.cos(), c[1] + r * a.sin()]
        })
        .collect()
}

/// The built-in figures, in no particular order (the UI sorts by name).
pub fn builtin_figures() -> Vec<Figure> {
    let mut figs = vec![
        heart(),
        flower(6),
        arrow(),
        lightning(),
        infinity(),
        outline("Losange", CYAN, vec![[0.0, 0.85], [0.6, 0.0], [0.0, -0.85], [-0.6, 0.0]]),
        outline("Pentagone", GREEN, polygon(5, 0.85)),
        outline("Hexagone", BLUE, polygon(6, 0.85)),
        crescent(),
        droplet(),
        spiral(),
        wave(),
        beating_heart(),
        ballerina(),
        star5(),
        star6(),
        circle_fig(),
        triangle(),
        square_fig(),
        octagon(),
        sun(),
        butterfly(),
        gear(),
        house(),
        fir_tree(),
        cloud(),
        music_note(),
        crown(),
        bowtie(),
        shooting_star(),
    ];
    for f in &mut figs {
        // Our own content is already in range; keep it safe anyway.
        let _ = f.validate();
    }
    figs
}

/// A heart curve (our own parametrisation), scaled into the field.
fn heart() -> Figure {
    let pts = curve(72, |t| {
        let a = t * TAU;
        let x = 16.0 * a.sin().powi(3);
        let y = 13.0 * a.cos() - 5.0 * (2.0 * a).cos() - 2.0 * (3.0 * a).cos() - (4.0 * a).cos();
        [x / 17.0, y / 17.0 + 0.1]
    });
    outline("Cœur", RED, pts)
}

/// A rose/flower of `petals` petals (r = cos(k·θ)).
fn flower(petals: usize) -> Figure {
    let k = petals as f32;
    let pts = curve(240, |t| {
        let a = t * TAU;
        let r = 0.9 * (k * a).cos().abs().max(0.02);
        [r * a.cos(), r * a.sin()]
    });
    outline(&format!("Fleur {petals} pétales"), MAGENTA, pts)
}

/// An upward arrow outline.
fn arrow() -> Figure {
    outline("Flèche", GREEN, vec![
        [-0.25, -0.8], [-0.25, 0.1], [-0.55, 0.1], [0.0, 0.8],
        [0.55, 0.1], [0.25, 0.1], [0.25, -0.8],
    ])
}

/// A zig-zag lightning bolt outline.
fn lightning() -> Figure {
    outline("Éclair", YELLOW, vec![
        [0.1, 0.85], [-0.45, 0.05], [-0.1, 0.05], [-0.35, -0.85],
        [0.45, 0.1], [0.08, 0.1], [0.35, 0.85],
    ])
}

/// A lemniscate (∞) through the origin.
fn infinity() -> Figure {
    let pts = curve(96, |t| {
        let a = t * TAU;
        let d = 1.0 + a.sin().powi(2);
        [0.85 * a.cos() / d, 0.5 * a.sin() * a.cos() / d]
    });
    outline("Infini", CYAN, pts)
}

/// A crescent moon: outer circle, back through an inner arc.
fn crescent() -> Figure {
    let outer = curve(48, |t| {
        let a = -PI / 2.5 + t * (TAU - 2.0 * PI / 2.5);
        [0.8 * a.cos(), 0.8 * a.sin()]
    });
    let inner = curve(32, |t| {
        let a = (TAU - PI / 2.5) - t * (TAU - 2.0 * PI / 2.5);
        [0.35 + 0.7 * a.cos(), 0.7 * a.sin()]
    });
    outline("Croissant", WHITE, outer.into_iter().chain(inner).collect())
}

/// A teardrop / water drop: a point at the top rounding into a disc.
fn droplet() -> Figure {
    let pts = curve(80, |t| {
        let a = t * TAU;
        // A circle pinched to a cusp at the top.
        let r = 0.7 * (1.0 - a.sin());
        [r * a.cos(), r * a.sin() - 0.1]
    });
    outline("Goutte", BLUE, pts)
}

/// An Archimedean spiral (an open stroke, not closed).
fn spiral() -> Figure {
    let pts = curve(200, |t| {
        let a = t * 5.0 * TAU;
        let r = 0.08 + 0.82 * t;
        [r * a.cos(), r * a.sin()]
    });
    one_frame("Spirale", vec![stroke(pts, GREEN)])
}

/// A sine wave across the field (an open stroke).
fn wave() -> Figure {
    let pts = curve(120, |t| {
        let x = -0.9 + 1.8 * t;
        [x, 0.5 * (t * 3.0 * TAU).sin()]
    });
    one_frame("Vague", vec![stroke(pts, CYAN)])
}

/// An animated heart that beats: four frames at different sizes, stepped
/// on the beat (the example animated figure, T-533).
fn beating_heart() -> Figure {
    let base = curve(72, |t| {
        let a = t * TAU;
        let x = 16.0 * a.sin().powi(3);
        let y = 13.0 * a.cos() - 5.0 * (2.0 * a).cos() - 2.0 * (3.0 * a).cos() - (4.0 * a).cos();
        [x / 17.0, y / 17.0 + 0.1]
    });
    let frames = [1.0_f32, 0.82, 1.0, 1.12]
        .into_iter()
        .map(|k| {
            let pts = closed(base.iter().map(|p| [p[0] * k, p[1] * k]).collect());
            FigureFrame { strokes: vec![stroke(pts, RED)] }
        })
        .collect();
    Figure { name: "Cœur qui bat".to_string(), frames, rate: 2.0, per: RateUnit::Beat, loop_mode: LoopMode::Loop, ..Figure::default() }
}

/// A low-poly segment of a limb from `a` (half-width `wa`) to `b`
/// (half-width `wb`): a closed tapered quad.
fn limb_quad(a: [f32; 2], b: [f32; 2], wa: f32, wb: f32) -> Vec<[f32; 2]> {
    let (dx, dy) = (b[0] - a[0], b[1] - a[1]);
    let len = (dx * dx + dy * dy).sqrt().max(1e-6);
    let (nx, ny) = (-dy / len, dx / len);
    closed(vec![
        [a[0] + nx * wa, a[1] + ny * wa],
        [b[0] + nx * wb, b[1] + ny * wb],
        [b[0] - nx * wb, b[1] - ny * wb],
        [a[0] - nx * wa, a[1] - ny * wa],
    ])
}

/// `p` rotated by `ang` radians around `c`.
fn rot_about(c: [f32; 2], p: [f32; 2], ang: f32) -> [f32; 2] {
    let (s, co) = ang.sin_cos();
    let (x, y) = (p[0] - c[0], p[1] - c[1]);
    [c[0] + x * co - y * s, c[1] + x * s + y * co]
}

/// A hologram ballerina: a low-poly body (head, torso, tutu, tapered limb
/// segments) in cyan, laced with a blue mesh and a constellation of lines
/// reaching out to drifting nodes. One arm raised high, the other held out,
/// on pointe with the other leg in passé. Eight frames: the arms breathe,
/// the tutu ripples, the network twinkles. Our own geometry, placed by
/// hand: nothing traced from any product's content.
fn ballerina() -> Figure {
    const N: usize = 8;
    let frames = (0..N)
        .map(|i| {
            let ph = i as f32 / N as f32 * TAU;
            let head_c = [0.03, 0.52];
            let head: Vec<[f32; 2]> = (0..7)
                .map(|k| {
                    let a = PI / 2.0 + k as f32 / 7.0 * TAU;
                    rot_about(head_c, [head_c[0] + 0.062 * a.cos(), head_c[1] + 0.08 * a.sin()], -0.25)
                })
                .collect();
            let (neck, shl, shr) = ([0.02, 0.42], [-0.10, 0.36], [0.12, 0.35]);
            // Raised arm breathes up and down; the side arm's hand flutters.
            let up = 0.12 * ph.sin();
            let el = rot_about(shl, [-0.22, 0.58], up);
            let wl = rot_about(shl, [-0.33, 0.79], up * 1.3);
            let hl = rot_about(shl, [-0.37, 0.88], up * 1.4);
            let fl = 0.06 * (ph + 1.0).sin();
            let er = [0.33, 0.34];
            let wr = rot_about(er, [0.52, 0.37], fl);
            let hr = rot_about(er, [0.61, 0.40], fl * 1.4);
            let (waist_l, waist_r, chest_l, chest_r) = ([-0.07, 0.11], [0.08, 0.11], [-0.09, 0.24], [0.11, 0.23]);
            let torso = closed(vec![shl, neck, shr, chest_r, waist_r, waist_l, chest_l]);
            // Tutu, flared to one side as in a turn; its hem ripples.
            let hem: Vec<[f32; 2]> = [[-0.17, -0.09], [-0.06, -0.17], [0.09, -0.19], [0.24, -0.15], [0.37, -0.06], [0.45, 0.03]]
                .iter()
                .enumerate()
                .map(|(k, p)| [p[0], p[1] + 0.02 * (2.0 * ph + k as f32).sin()])
                .collect();
            let mut tutu = vec![waist_l, waist_r, [0.25, 0.10]];
            tutu.extend(hem.iter().rev());
            let tutu = closed(tutu);
            // Standing leg on pointe; the other in passé, foot at the knee.
            let (hip_l, knee_l, ankle_l, toe_l) = ([-0.03, -0.13], [-0.04, -0.48], [-0.02, -0.80], [-0.01, -0.93]);
            let (hip_r, knee_r, ankle_r, toe_r) = ([0.11, -0.14], [0.34, -0.35], [0.04, -0.46], [-0.01, -0.49]);
            let mut strokes = vec![
                stroke(closed(head), CYAN),
                stroke(torso, CYAN),
                stroke(tutu, CYAN),
                stroke(limb_quad(shl, el, 0.035, 0.03), CYAN),
                stroke(limb_quad(el, wl, 0.03, 0.022), CYAN),
                stroke(limb_quad(wl, hl, 0.022, 0.008), CYAN),
                stroke(limb_quad(shr, er, 0.035, 0.03), CYAN),
                stroke(limb_quad(er, wr, 0.03, 0.022), CYAN),
                stroke(limb_quad(wr, hr, 0.022, 0.008), CYAN),
                stroke(limb_quad(hip_l, knee_l, 0.055, 0.035), CYAN),
                stroke(limb_quad(knee_l, ankle_l, 0.035, 0.02), CYAN),
                stroke(limb_quad(ankle_l, toe_l, 0.02, 0.01), CYAN),
                stroke(limb_quad(hip_r, knee_r, 0.055, 0.035), CYAN),
                stroke(limb_quad(knee_r, ankle_r, 0.035, 0.02), CYAN),
                stroke(limb_quad(ankle_r, toe_r, 0.02, 0.01), CYAN),
            ];
            // The mesh: torso diagonals and the tutu's pleats.
            for seg in [[shl, waist_r], [shr, waist_l], [neck, chest_l], [neck, chest_r], [chest_l, chest_r]] {
                strokes.push(stroke(seg.to_vec(), BLUE));
            }
            let mid = [0.01, 0.11];
            for h in &hem {
                strokes.push(stroke(vec![mid, *h], BLUE));
            }
            // The constellation: drifting nodes wired to the body, two in
            // three lit on each frame, in turn.
            let nodes = [[-0.55, 0.55], [-0.62, 0.05], [-0.45, -0.40], [0.55, 0.70], [0.72, 0.15], [0.60, -0.30], [0.30, -0.72], [-0.30, 0.92], [0.22, 0.85]];
            let joints = [hl, el, hem[0], hr, hr, hem[5], knee_r, hl, head_c];
            for (k, (n, j)) in nodes.iter().zip(joints).enumerate() {
                if (k + i) % 3 != 0 {
                    let kf = k as f32;
                    let node = [n[0] + 0.03 * (ph + kf).sin(), n[1] + 0.03 * (ph + kf * 1.7).cos()];
                    strokes.push(stroke(vec![j, node], BLUE));
                }
            }
            // A glint on the floor under the pointe.
            strokes.push(stroke(vec![[-0.18, -0.96], [0.16, -0.96]], BLUE));
            FigureFrame { strokes }
        })
        .collect();
    Figure { name: "Ballerine hologramme".to_string(), frames, rate: 4.0, per: RateUnit::Beat, loop_mode: LoopMode::Loop, ..Figure::default() }
}

/// A star of `points` points: outer radius `ro`, inner `ri`, first spike up.
fn star(points: usize, ro: f32, ri: f32) -> Vec<[f32; 2]> {
    (0..2 * points)
        .map(|i| {
            let r = if i % 2 == 0 { ro } else { ri };
            let a = PI / 2.0 + i as f32 / (2 * points) as f32 * TAU;
            [r * a.cos(), r * a.sin()]
        })
        .collect()
}

