/// A shooting star: a small star in the corner with a trailing streak.
fn shooting_star() -> Figure {
    let star_pts: Vec<[f32; 2]> = star(5, 0.32, 0.13).into_iter().map(|p| [p[0] + 0.45, p[1] + 0.4]).collect();
    let trail = vec![[0.45, 0.4], [-0.3, -0.3], [-0.75, -0.72]];
    one_frame("Étoile filante", vec![stroke(closed(star_pts), WHITE), stroke(trail, CYAN)])
}

// ---------------------------------------------------------------------------
// Wireframe 3D objects
// ---------------------------------------------------------------------------

/// Builds an object from raw vertices and edges: the vertices are centred
/// and scaled so the farthest sits on the unit sphere, the usual look
/// (one turn per 8 beats, a gentle second axis, soft perspective).
fn object(name: &str, color: [u8; 3], verts: Vec<[f32; 3]>, edges: Vec<[u32; 2]>) -> WireObject {
    let c = centre(&verts);
    let centred: Vec<[f32; 3]> = verts.iter().map(|v| [v[0] - c[0], v[1] - c[1], v[2] - c[2]]).collect();
    let max = centred.iter().map(|v| (v[0] * v[0] + v[1] * v[1] + v[2] * v[2]).sqrt()).fold(0.0_f32, f32::max).max(1e-6);
    let vertices = centred.into_iter().map(|v| [v[0] / max, v[1] / max, v[2] / max]).collect();
    WireObject { name: name.to_string(), vertices, edges, color, ..WireObject::default() }
}

/// The centroid of a point cloud.
fn centre(verts: &[[f32; 3]]) -> [f32; 3] {
    let n = verts.len().max(1) as f32;
    let mut c = [0.0; 3];
    for v in verts {
        for k in 0..3 {
            c[k] += v[k];
        }
    }
    c.map(|x| x / n)
}

/// Edges linking every pair of vertices whose distance is within 1 % of the
/// shortest one: the natural wireframe of a regular polyhedron.
fn nearest_edges(verts: &[[f32; 3]]) -> Vec<[u32; 2]> {
    let dist = |a: [f32; 3], b: [f32; 3]| ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt();
    let mut min = f32::INFINITY;
    for i in 0..verts.len() {
        for j in i + 1..verts.len() {
            min = min.min(dist(verts[i], verts[j]));
        }
    }
    let mut edges = Vec::new();
    for i in 0..verts.len() {
        for j in i + 1..verts.len() {
            if dist(verts[i], verts[j]) <= min * 1.01 {
                edges.push([i as u32, j as u32]);
            }
        }
    }
    edges
}

